#include <gtest/gtest.h>

#include <cstdio>
#include <cstdlib>

#include "esphome/components/logger/logger.h"
#include "esphome/core/application.h"

/*
Replaces the main.cpp generated by ESPHome (copied over it by `includes`): runs the tests and exits with their result.
The code ESPHome generates from cpp-tests.yaml goes in original_setup(), which never runs: the configuration is only
there to compile the component, its platforms and their dependencies. The tests create the objects they need.
*/

// ========== AUTO GENERATED INCLUDE BLOCK BEGIN ===========
// ========== AUTO GENERATED INCLUDE BLOCK END ==========="

void original_setup() {
  // ========== AUTO GENERATED CODE BEGIN ===========
  // =========== AUTO GENERATED CODE END ============
}

void setup() {
  // Constructed as the generated code does, before anything uses it
  new (&esphome::App) esphome::Application;

  // Logging calls the global logger without checking it. All the messages are formatted, so that the tests cover the
  // logging code too, but they are printed only with KYO_TESTS_LOG set
  static esphome::logger::Logger logger(0);
  logger.set_log_level(std::getenv("KYO_TESTS_LOG") != nullptr ? ESPHOME_LOG_LEVEL : ESPHOME_LOG_LEVEL_NONE);
  logger.pre_setup();

  ::testing::InitGoogleTest();
  int result = RUN_ALL_TESTS();
  // A test file that did not reach the build would otherwise pass as an empty run
  if (::testing::UnitTest::GetInstance()->total_test_count() == 0) {
    std::fprintf(stderr, "No tests were linked into this binary\n");
    result = 1;
  }
  std::exit(result);
}

void loop() {}
